// Normalisatie helpers
function cleanDateTime(dateStr) {
    if (!dateStr) return null;
    try {
        var d = new Date(dateStr);
        if (isNaN(d.getTime())) return null;
        d.setUTCMilliseconds(0);
        return d.toISOString().replace('.000Z', 'Z');
    } catch (e) { return null; }
}

function formatInteger(val) {
    if (val === null || val === undefined) return 0;
    var n = parseInt(val);
    return isNaN(n) ? 0 : n;
}

var rows = msg.payload.list || [];

var messages = rows.map(function(r) {
    return {
        topic: "umh/v1/smc/vienna/_work_order/process",
        payload: JSON.stringify({
            order_nr: String(r.order_nr || "").trim(),
            product: String(r.product || "").trim(),
            qty: formatInteger(r.qty),
            customer: String(r.customer || "").trim(),
            priority: formatInteger(r.priority) || null,
            due_date: cleanDateTime(r.due_date),
            status: String(r.status || "Nieuw").trim()
        })
    };
});

node.status({text: rows.length + " werkorders → MQTT (genormaliseerd)"});
return [messages];
